#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct COAT {
    pub ID: alloc::string::String,
    pub NAME: Option<alloc::string::String>,
    pub KIND: coaKind,
    pub NORAD_CAT_ID: u32,
    pub GROUP_ID: Option<alloc::string::String>,
    pub EVENT_STANDARD: Option<alloc::string::String>,
    pub EVENT_ID: Option<alloc::string::String>,
    pub EVENT_EPOCH: Option<alloc::string::String>,
    pub LEAD_SECONDS: f64,
    pub RETURN_WITHIN_SECONDS: f64,
    pub PREPARATION_SECONDS: f64,
    pub CHECKOUT_SECONDS: f64,
    pub DELTA_V_BUDGET_M_S_PER_YEAR: f64,
    pub STEPS: Option<alloc::vec::Vec<COAStepT>>,
    pub PLAN_ID: Option<alloc::string::String>,
}

impl Default for COAT {
    fn default() -> Self {
        Self {
            ID: alloc::string::ToString::to_string(""),
            NAME: None,
            KIND: coaKind::UNSPECIFIED,
            NORAD_CAT_ID: 0,
            GROUP_ID: None,
            EVENT_STANDARD: None,
            EVENT_ID: None,
            EVENT_EPOCH: None,
            LEAD_SECONDS: 0.0,
            RETURN_WITHIN_SECONDS: 0.0,
            PREPARATION_SECONDS: 0.0,
            CHECKOUT_SECONDS: 0.0,
            DELTA_V_BUDGET_M_S_PER_YEAR: 0.0,
            STEPS: None,
            PLAN_ID: None,
        }
    }
}

impl COAT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<COA<'b>> {
        let ID = Some({
            let x = &self.ID;
            _fbb.create_string(x)
        });
        let NAME = self.NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let KIND = self.KIND;
        let NORAD_CAT_ID = self.NORAD_CAT_ID;
        let GROUP_ID = self.GROUP_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let EVENT_STANDARD = self.EVENT_STANDARD.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let EVENT_ID = self.EVENT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let EVENT_EPOCH = self.EVENT_EPOCH.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let LEAD_SECONDS = self.LEAD_SECONDS;
        let RETURN_WITHIN_SECONDS = self.RETURN_WITHIN_SECONDS;
        let PREPARATION_SECONDS = self.PREPARATION_SECONDS;
        let CHECKOUT_SECONDS = self.CHECKOUT_SECONDS;
        let DELTA_V_BUDGET_M_S_PER_YEAR = self.DELTA_V_BUDGET_M_S_PER_YEAR;
        let STEPS = self.STEPS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let PLAN_ID = self.PLAN_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        COA::create(_fbb, &COAArgs{
            ID,
            NAME,
            KIND,
            NORAD_CAT_ID,
            GROUP_ID,
            EVENT_STANDARD,
            EVENT_ID,
            EVENT_EPOCH,
            LEAD_SECONDS,
            RETURN_WITHIN_SECONDS,
            PREPARATION_SECONDS,
            CHECKOUT_SECONDS,
            DELTA_V_BUDGET_M_S_PER_YEAR,
            STEPS,
            PLAN_ID,
        })
    }
}

